def load_config(uri):
    """Load and parse a JSON configuration file."""

    if not uri or not uri.strip():
        raise ValueError("Configuration URI is required.")

    directory, filename = uri.rsplit("/", 1)

    entries = mssparkutils.fs.ls(directory)

    matches = [
        entry
        for entry in entries
        if entry.isFile and entry.name == filename
    ]

    if len(matches) != 1:
        raise FileNotFoundError(
            f"Configuration file not found: {uri}"
        )

    content = mssparkutils.fs.head(
        uri,
        matches[0].size
    )

    config = json.loads(content)

    if not isinstance(config, dict):
        raise ValueError(
            f"Invalid configuration structure: {uri}"
        )

    return config

