def discover_source_files(config, dataset):
    """Discover files using configured dataset metadata."""

    source = dataset["source"]

    source_path = build_storage_path(
        config,
        source["layer"],
        source["directory"]
    )
    entries = mssparkutils.fs.ls(source_path)
    return sorted(
        [
            entry
            for entry in entries
            if entry.isFile
            and fnmatchcase(
                entry.name,
                source["file_pattern"]
            )
        ],
        key=lambda entry: entry.name
    )


